function evalSwitchMode(mode){
  sfx('click');
  const cWrap=document.getElementById('evalConceptWrap'),critWrap=document.getElementById('evalCritWrap');
  const cBtn=document.getElementById('evalModeBtnConcept'),critBtn=document.getElementById('evalModeBtnCrit');
  if(mode==='crit'){
    cWrap.style.display='none';critWrap.style.display='block';
    cBtn.classList.remove('active');cBtn.setAttribute('aria-selected','false');
    critBtn.classList.add('active');critBtn.setAttribute('aria-selected','true');
    if(!window._evalCritData)genEvalCrit();
  }else{
    critWrap.style.display='none';cWrap.style.display='block';
    critBtn.classList.remove('active');critBtn.setAttribute('aria-selected','false');
    cBtn.classList.add('active');cBtn.setAttribute('aria-selected','true');
  }
}

const critCaseBank=[{"txt":"Llega reenviado al grupo de la familia: «el uno por ciento más rico tiene más que la mitad del mundo junta». Viene de un informe real y la cuenta está bien hecha."},{"txt":"En la aldea dicen que antes llovía más y que el pozo aguantaba todo el verano. Varias personas mayores coinciden y a nadie le gusta que le pongan la memoria en duda."},{"txt":"Pasa una tormenta fuerte y a las dos semanas el frijol sube. En la casa dicen que es el clima, en la pulpería que es el intermediario, y el noticiero dice las dos cosas el mismo día."},{"txt":"Se afirma que este país emite muy poco comparado con los grandes. También es cierto que la ropa que se cose aquí se usa allá, y que la energía para coserla se cuenta de este lado."},{"txt":"Un titular dice que el calentamiento va a ser de cuatro grados. El informe del que sale da un rango probable de 2,5 a 4 °C, con 3 °C como mejor estimación."},{"txt":"Alguien sostiene que la desigualdad siempre sube, sin decir de qué desigualdad habla ni de qué años, y cita de memoria un libro que no ha leído entero."},{"txt":"Se discute si arreglar el techo de la escuela este año o el próximo, y cada bando trae su cuenta, y las dos cuentas están bien hechas y dan resultados contrarios."},{"txt":"Una misión de esta casa publica una cifra sin decir de qué año es ni de dónde sale, y una familia la copia en su cuaderno y la usa para discutir en el trabajo."}];
const critCaseQuestions=["1. Di qué mide esa cifra exactamente, con esas palabras: ingreso o riqueza, antes o después de impuestos, dentro o entre países, emisiones territoriales o de consumo.","2. Di de qué fuente sale y de qué año, y cuál es su horquilla. Si el titular tomó la punta en vez del centro, señálalo.","3. Trae la auditoría que va al lado: quién ha discutido esa cifra o esa tesis, con qué argumento, y qué queda en pie después de la objeción.","4. Di quién paga esa factura y en qué plazo, distingue lo que es dato de lo que es decisión, y escribe qué dato te haría cambiar de opinión."];
const critCaseGuides=["Se empieza por la definición, que es el paso que casi nadie da y el que resuelve la mitad de los casos. La misma palabra nombra cosas distintas: ingreso no es riqueza, antes de impuestos no es después de impuestos, y emisiones territoriales no son emisiones de consumo. Una respuesta buena escribe la definición con las palabras técnicas y después traduce lo que eso significa para el retrato que el titular deja en la cabeza.","Después van la fuente con su año y la horquilla. Si la cifra tiene rango, se dice entero y se señala la mejor estimación; si el titular tomó un extremo, se dice cuál y en qué dirección empuja. Aquí se cae en la trampa propia de la etapa, que es escoger la punta que conviene, y se cae desde los dos lados con el mismo informe: con 2,5 a 4 °C se puede alarmar y tranquilizar sin mentir en ninguna de las dos.","La auditoría entra al lado y no debajo, igual que en toda esta ruta. Piketty va con Rognlie, que mostró en 2015 que casi todo el aumento de la participación del capital viene de la vivienda, y con el episodio del Financial Times de 2014, que Piketty respondió publicando sus datos. La curva del elefante va con Corlett, de 2016. Los modelos del clima van con Pindyck, de 2013. Y una respuesta muy buena dice qué queda en pie después de cada objeción, porque casi siempre queda algo y decir que no queda nada es el error simétrico.","Al final se separa lo que es dato de lo que es decisión, que es la distinción más útil de la etapa: que llevamos alrededor de 1,1 °C es un dato; que haya que quedarse por debajo de 2 °C es una decisión, la del Acuerdo de París de 2015. Y la tasa de descuento, que es donde discrepan Stern y Nordhaus, es una decisión moral escrita como número, no un resultado científico. Se cierra diciendo quién paga y en qué plazo, y con el renglón que esta casa exige siempre: qué dato haría cambiar la conclusión, escrito antes de discutir y no después."];

const critErrorBank=[{"txt":"\"Va a subir cuatro grados\".","g1":"Toma la punta del rango y la cuenta como si fuera el número: el informe da de 2,5 a 4 °C con 3 °C como mejor estimación, así que la frase cita bien y engaña igual.","g2":"La corrección dice la horquilla entera, señala la mejor estimación y nombra la fuente con su año."},{"txt":"\"El uno por ciento tiene más que la mitad del mundo, así que la mitad del mundo no tiene nada\".","g1":"La primera parte es cierta y mide riqueza neta; la segunda no se sigue, porque con esa vara un graduado endeudado aparece más pobre que alguien sin deudas y sin nada.","g2":"Se corrige diciendo qué mide la cifra y, si lo que se quiere mostrar es concentración, usando participaciones de ingreso y de riqueza con su metodología."},{"txt":"\"La desigualdad siempre sube\".","g1":"No dice de qué desigualdad ni de qué años, y en una de sus lecturas es falsa: entre países bajó mientras dentro de los países ricos subía, que es lo que muestra la curva del elefante.","g2":"Se corrige diciendo cuál de las dos, en qué periodo y con qué fuente, y añadiendo la objeción de Corlett a la forma de la curva."},{"txt":"\"Como el titular estaba mal, el problema no existe\".","g1":"Es el error simétrico y el más cómodo: desarmar una cifra mal contada es el principio del trabajo, no el final, y quien se queda ahí cambió una consigna por otra más elegante.","g2":"Se corrige poniendo la cifra buena en el lugar de la mala, no borrando el tema."},{"txt":"\"Si la ciencia da un rango, es que no se sabe nada\".","g1":"Un rango no es ignorancia: es saber con precisión cuánto no se sabe, y eso es más que cualquier número redondo sin fuente.","g2":"Se corrige explicando qué significa el rango y dónde está la mejor estimación."},{"txt":"\"Aquí emitimos poco y punto\".","g1":"Falta decir cómo se cuenta: las emisiones territoriales y las de consumo dan números distintos para el mismo país, y las dos son legítimas.","g2":"Se corrige diciendo cuál de las dos contabilidades se está usando, y sosteniendo a la vez que aquí se emite poco por persona y que aquí se sufre mucho."}];

const critDecisionBank=["El titular del uno por ciento ya está en el grupo de la familia: ¿qué se contesta, en tres renglones, sin quedar de aguafiestas ni de repetidor?","La aldea sostiene que antes llovía más: ¿cómo se respeta la memoria sin confundirla con una serie, y qué se propone hacer a partir de esta semana?","El frijol subió después de la tormenta: ¿qué tres causas se ponen sobre la mesa y qué datos harían falta para saber cuál explica cuánto?","Hay que explicarle a la familia por qué «aquí emitimos poco» y «aquí sufrimos mucho» son las dos ciertas: ¿cómo se dice sin que parezca una excusa?","Angelly pregunta si es lo mismo que todos ganen parecido a que cualquiera pueda llegar a cualquier parte: ¿qué se contesta y con qué medición?","La frase de Jael ya está escrita en el cuaderno: ¿se borra o se corrige, y con qué tres renglones se reescribe para que sirva para discutir?","Alguien quiere usar esta etapa para señalar a un funcionario con pleito abierto: ¿qué dice la regla de selección de la materia, y cómo se escribe el caso para que entre como categoría?","La casa se audita a sí misma: ¿qué reglas se impone sobre las cifras que publica, y qué señal obligaría a corregir una misión ya publicada?"];
const critDecisionGuide="La decisión correcta sigue siempre el mismo orden, y el orden es el método. Primero se dice qué mide la cifra exactamente, con las palabras tecnicas y no con las del titular, porque la misma palabra nombra cosas distintas: ingreso no es riqueza, antes de impuestos no es despues de impuestos, y emisiones territoriales no son emisiones de consumo. Ese paso resuelve la mitad de los casos y casi nadie lo da. Despues va la fuente con su año, con nombre y no con un se dice que, y va la horquilla entera si la cifra tiene rango, señalando cual es la mejor estimacion; y si el titular tomo un extremo se dice cual y en que direccion empuja, porque el modo de fallar de esta etapa es escoger la punta del rango y lo cometen los dos bandos con el mismo informe. Luego entra la auditoria al lado y no debajo, igual que en toda esta ruta: Piketty de 2014 va con Rognlie de 2015, que mostro que casi todo el aumento de la participacion del capital viene de la vivienda, y con el episodio del Financial Times de 2014, al que Piketty respondio publicando sus datos; la curva del elefante de Lakner y Milanovic va con la objecion de Corlett de 2016 sobre que su forma depende de que paises entren; y los modelos del clima van con Pindyck de 2013, que advirtio desde dentro de la profesion que aparentan una precision que no tienen. Y de cada objecion se dice que queda en pie despues, porque casi siempre queda algo. Al final se separa lo que es dato de lo que es decision, que es la distincion mas util de la etapa: que llevamos alrededor de 1,1 grados esta medido, que haya que quedarse por debajo de 2 es una decision politica del Acuerdo de Paris de 2015, y la tasa de descuento, donde discrepan Stern y Nordhaus mirando la misma fisica, es una decision moral escrita como numero. Se cierra diciendo quien paga esa factura y en que plazo, y con el renglon que esta casa exige siempre: que dato haria cambiar la conclusion, escrito antes de discutir y no despues. Y encima de todo, el aviso que impide el error simetrico: que una cifra este mal usada no borra el problema que describe.";

const critCompareBank=[{"a":"Escribir «entre 2,5 y 4 °C, con 3 como mejor estimación, según el IPCC de 2021».","b":"Escribir «va a subir cuatro grados».","ga":"Caso A: dice la horquilla, la mejor estimación y la fuente con su año, así que quien lo lea puede comprobarlo y puede discutirlo.","gb":"Caso B: toma la punta del rango, y aunque cite un informe verdadero deja en la cabeza un número que el informe no dijo.","gr":"La diferencia no es de tono sino de comprobabilidad: solo la primera se puede verificar y solo la primera enseña a leer."},{"a":"Citar a Piketty con Rognlie y con el episodio del Financial Times al lado.","b":"Citar a Piketty como si nadie lo hubiera discutido.","ga":"Caso A: deja la discusión donde está de verdad, que es qué parte del aumento viene de la vivienda y qué habría que hacer con eso.","gb":"Caso B: usa a un autor como bandera y esconde diez años de auditoría, que es el vicio que esta materia enseña a cazar.","gr":"La regla no cambia según de qué lado caiga la objeción: media cita es media cita."},{"a":"Decir «esto es un dato» y «esto es una decisión», separado.","b":"Mezclar las dos cosas en la misma frase con el mismo tono.","ga":"Caso A: permite discutir la decisión sin negar el dato, que es la única conversación que puede terminar en algo.","gb":"Caso B: convierte una posición moral en una supuesta autoridad científica, y del otro lado permite negar el dato porque la decisión no gusta.","gr":"Que llevamos 1,1 °C es un dato; quedarse bajo 2 °C es una decisión; y la tasa de descuento es una decisión moral escrita como número."},{"a":"Anotar cada semana el precio del frijol durante tres años.","b":"Discutir de memoria si antes estaba más barato.","ga":"Caso A: construye una serie, que es lo único que puede zanjar la discusión, y lo puede hacer cualquiera con un cuaderno.","gb":"Caso B: enfrenta dos memorias, y las memorias guardan sustos y no promedios, así que la discusión no termina nunca.","gr":"Una memoria es un dato; una serie es una prueba. Eso lo entendió Keeling en 1958 y lo puede repetir una niña con un cuaderno de espiral."}];

const critCauseBank=[{"cause":"Se repite una cifra sin decir qué mide.","guide":"Casi todas las cifras que circulan son verdaderas y aun así dejan un retrato falso, porque la palabra que las nombra cubre cosas distintas. Ingreso no es riqueza; antes de impuestos no es después de impuestos; territorial no es de consumo. Quien no dice la definición no está mintiendo, pero está transmitiendo un error, y el error viaja más rápido que la corrección."},{"cause":"Se toma la punta del rango y se cuenta como el número.","guide":"Es el modo de fallar propio de esta etapa y lo cometen los dos bandos con el mismo informe. Con la horquilla de 2,5 a 4 °C se puede titular alarmando o tranquilizando sin decir una sola falsedad. La lectura honrada dice el rango entero y señala la mejor estimación, y solo después opina. Un número redondo sin rango es casi siempre una conclusión disfrazada de dato."},{"cause":"Se cita una tesis sin su auditoría.","guide":"Es la misma falta que en las etapas anteriores, aplicada a cifras. Piketty va con Rognlie de 2015 y con el episodio del Financial Times de 2014; la curva del elefante va con Corlett de 2016; los modelos del clima van con Pindyck de 2013. Y hay que decir qué queda en pie después de cada objeción, porque casi siempre queda algo: la auditoría rara vez derriba, casi siempre matiza y cambia el remedio."},{"cause":"Se confunde un dato con una decisión.","guide":"Que llevamos alrededor de 1,1 °C es un dato, medido. Que haya que quedarse bien por debajo de 2 °C es una decisión, la del Acuerdo de París de 2015. Y la tasa de descuento, donde discrepan Stern y Nordhaus, es una decisión moral escrita como número. Mezclar las dos cosas hace dos daños: convierte una posición moral en autoridad científica, y le da al otro lado la excusa para negar el dato porque la decisión no le gusta."},{"cause":"Se desarma un titular y se da el tema por cerrado.","guide":"Es el error simétrico, y el más cómodo de todos, porque uno queda de listo sin haber estudiado nada. Que el titular del uno por ciento se lea mal no borra la concentración de la riqueza, que está medida por otras vías; que alguien exagere con el clima no baja la raya del termómetro. Desarmar una cifra mal contada es el principio del trabajo: lo que sigue es poner la cifra buena en su lugar."},{"cause":"Se usa la etapa para señalar a alguien con pleito abierto.","guide":"Rompe la regla de selección de la materia. La asimetría de emitir poco y sufrir mucho se estudia con cifras, con su fuente y su año, y como categoría: no se le pone la etiqueta a ningún funcionario, a ningún partido ni a nadie en campaña. La herramienta sirve para pensar el mecanismo y para pedir con números en vez de con adjetivos, que además funciona mejor y dura más de una semana."}];
const critEffectBank=[{"effect":"El titular del uno por ciento entró al expediente con su definición y su fuente.","guide":"Se anotó que mide riqueza neta, es decir lo que se tiene menos lo que se debe, y que con esa vara un graduado endeudado aparece más pobre que alguien sin deudas y sin tierra. Y se anotó lo segundo, que es lo difícil: eso no borra la concentración de la riqueza, que está medida por otras vías. Para mostrar concentración sirven mejor las participaciones de ingreso y de riqueza publicadas con su metodología."},{"effect":"La aldea empezó a llevar un cuaderno con la fecha en que se seca el pozo.","guide":"Es la lección de Keeling en pequeño: una memoria es un dato y una serie es una prueba. No se le quitó la razón a nadie ni se despreció la memoria de los mayores; se le añadió lo único que puede zanjar la discusión, que es anotar. Y se dejó escrito lo que todavía no se puede afirmar: que un verano concreto sea por el calentamiento requiere ciencia de atribución, y sin ella lo honrado es decir que encaja y no que está probado."},{"effect":"La casa pudo sostener a la vez que aquí se emite poco y que aquí se sufre mucho.","guide":"Porque son dos cifras distintas y las dos tienen fuente: emisiones por persona por un lado, exposición y capacidad de reponerse por otro. Y porque se dijo cuál de las dos contabilidades se estaba usando, la territorial o la de consumo, que dan números distintos para el mismo país. Ninguna de las dos frases cancela a la otra, y quien necesite que una cancele a la otra está discutiendo otra cosa."},{"effect":"La frase de Jael quedó reescrita en tres renglones que se pueden comprobar.","guide":"De «la desigualdad siempre sube» se pasó a: la desigualdad de ingreso dentro de los países ricos subió desde los años ochenta, la desigualdad entre países bajó en el mismo periodo, las dos cosas están en el trabajo de Lakner y Milanović, y la forma de esa curva tiene encima la objeción de Corlett de 2016. Se perdió la contundencia y se ganó lo único que importa: que ahora se puede discutir y se puede comprobar."},{"effect":"La casa se auditó a sí misma y dejó por escrito sus reglas sobre cifras.","guide":"Toda cifra publicada lleva fuente y año; las que tienen rango se escriben con su rango; las fichas se imprimen en papel para que sirvan sin datos ni batería, porque una misión que exige teléfono y luz tiene su propia factura de desigualdad de acceso. Y la señal que obligaría a cambiar: si una familia encuentra una cifra sin fuente, se corrige la misión, no se explica por qué estaba bien."},{"effect":"La discusión del techo de la escuela terminó en una decisión y no en una pelea.","guide":"Porque se separó lo que era cuenta de lo que era gusto. Las dos cuentas estaban bien hechas y daban resultados contrarios porque valoraban distinto el mañana, que es exactamente la tasa de descuento de Stern y Nordhaus traída a la cocina. Al decirlo en voz alta, la discusión dejó de ser sobre quién sumaba mal y pasó a ser sobre cuánto pesa el nieto que va a pasar por ese techo, que es una pregunta que sí se puede contestar entre personas."}];

function genEvalCrit(){
  sfx('click');
  _injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});const _sC=document.getElementById('evalCritFormaSel');if(_sC&&parseInt(_sC.value,10))evalCritFormNum=Math.min(EVAL_FORMAS,Math.max(1,parseInt(_sC.value,10)));const cf=evalCritFormNum;window._currentEvalCritForm=cf;const rngC=_evalRng(200000+cf);evalCritFormNum=(evalCritFormNum%EVAL_FORMAS)+1;_injectFormaSel('genEvalCrit','evalCritFormaSel',evalCritFormNum,function(v){evalCritFormNum=v;});saveProgress();
  document.getElementById('evalcrit-screen-title').textContent=`🌡️ La cifra sobre la mesa · Forma ${cf} · Las dos facturas · Ruta del Expediente Dorado`;
  evalCritAnsVisible=false;
  const out=document.getElementById('evalCritOut');out.innerHTML='';

  const kase=_rotaF(critCaseBank,cf);
  const s1=document.createElement('div');
  s1.innerHTML=`<div class="eval-section-title">I. La cifra sobre la mesa <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${kase.txt}</div>${critCaseQuestions.map((q,i)=>`<div class="crit-q-block"><div class="crit-q-label">${q}</div><textarea class="crit-textarea" rows="2" aria-label="${q}"></textarea><div class="crit-pauta">${critCaseGuides[i]}</div></div>`).join('')}<div class="crit-selfscore"><label for="critScore0">Obtenido:</label><input type="number" id="critScore0" class="crit-score-input" data-score="0" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s1);

  const err=_rotaF(critErrorBank,cf);
  const s2=document.createElement('div');
  s2.innerHTML=`<div class="eval-section-title">II. Corrige el error <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${err.txt}</div><p style="font-size:0.85rem;margin-bottom:0.5rem;">Identifica <strong>dos errores</strong> y corrígelos con tus propias palabras:</p><div class="crit-q-block"><div class="crit-q-label">Error 1 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 1 y su corrección"></textarea><div class="crit-pauta">${err.g1}</div></div><div class="crit-q-block"><div class="crit-q-label">Error 2 y su corrección:</div><textarea class="crit-textarea" rows="2" aria-label="Error 2 y su corrección"></textarea><div class="crit-pauta">${err.g2}</div></div><div class="crit-selfscore"><label for="critScore1">Obtenido:</label><input type="number" id="critScore1" class="crit-score-input" data-score="1" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s2);

  const dec=_rotaF(critDecisionBank,cf);
  const s3=document.createElement('div');
  s3.innerHTML=`<div class="eval-section-title">III. Toma de decisiones bajo presión <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-scenario">${dec}</div><div class="crit-q-block"><div class="crit-q-label">¿Qué mide exactamente esta cifra, de qué fuente y de qué año sale, y cuál es su horquilla? Nombra la auditoría que va al lado con su etiqueta, di si el titular tomó la punta o el centro, y separa lo que es dato de lo que es decisión, diciendo quién paga y en qué plazo.</div><textarea class="crit-textarea" rows="4" aria-label="Recomendación y justificación"></textarea><div class="crit-pauta">${critDecisionGuide}</div></div><div class="crit-selfscore"><label for="critScore2">Obtenido:</label><input type="number" id="critScore2" class="crit-score-input" data-score="2" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s3);

  const cmp=_rotaF(critCompareBank,cf);
  const s4=document.createElement('div');
  s4.innerHTML=`<div class="eval-section-title">IV. Comparación razonada <span class="eval-pts">20 pts</span></div><div class="eval-item"><div class="crit-compare-grid"><div class="crit-compare-box"><h5>Caso A</h5>${cmp.a}</div><div class="crit-compare-box"><h5>Caso B</h5>${cmp.b}</div></div><div class="crit-q-block"><div class="crit-q-label">1. ¿Cuál de los dos se puede comprobar y cuál solo se puede repetir? 2. ¿Por qué no enseñan lo mismo a quien los lee?</div><textarea class="crit-textarea" rows="4" aria-label="Comparación razonada de los casos A y B"></textarea><div class="crit-pauta">Caso A: ${cmp.ga} · Caso B: ${cmp.gb} · ${cmp.gr}</div></div><div class="crit-selfscore"><label for="critScore3">Obtenido:</label><input type="number" id="critScore3" class="crit-score-input" data-score="3" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s4);

  const causes=_pickF(critCauseBank,2,rngC),effects=_pickF(critEffectBank,3,rngC);
  let ceRows='';
  causes.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Causa</span>${it.cause}</div><div class="crit-ce-cell"><span class="crit-ce-tag">Efecto</span><textarea class="crit-textarea" rows="2" aria-label="Efecto de: ${it.cause}" placeholder="Escribe el efecto..."></textarea></div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  effects.forEach((it,i)=>{ceRows+=`<div class="crit-ce-item"><div class="crit-ce-row"><div class="crit-ce-cell"><span class="crit-ce-tag">Causa</span><textarea class="crit-textarea" rows="2" aria-label="Causa de: ${it.effect}" placeholder="Escribe la causa..."></textarea></div><div class="crit-ce-cell crit-ce-given"><span class="crit-ce-tag">Efecto</span>${it.effect}</div></div><div class="crit-pauta">${it.guide}</div></div>`;});
  const s5=document.createElement('div');
  s5.innerHTML=`<div class="eval-section-title">V. Análisis de causas y efectos <span class="eval-pts">20 pts</span></div><div class="eval-item">${ceRows}<div class="crit-selfscore"><label for="critScore4">Obtenido:</label><input type="number" id="critScore4" class="crit-score-input" data-score="4" min="0" max="20" value="0"> <span>de 20 pts</span></div></div>`;
  out.appendChild(s5);

  window._evalCritData={kase,err,dec,cmp,causes,effects};
  const totalPanel=document.createElement('div');totalPanel.id='evalCritTotalResult';totalPanel.className='crit-total-panel';totalPanel.innerHTML='<strong>🧮 Autoevaluación:</strong> responde cada sección, compara con la <em>Pauta</em> y anota tu puntaje (0 a 20) en cada casilla. Luego presiona <em>Calcular Total</em>.';out.appendChild(totalPanel);
  fin('s-evaluacion');
}
function toggleEvalCritAns(){evalCritAnsVisible=!evalCritAnsVisible;document.querySelectorAll('#evalCritOut .crit-pauta').forEach(el=>el.style.display=evalCritAnsVisible?'block':'none');sfx('click');}
function calcCritTotal(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  let total=0;
  document.querySelectorAll('#evalCritOut .crit-score-input').forEach(inp=>{let v=parseInt(inp.value)||0;v=Math.max(0,Math.min(20,v));inp.value=v;total+=v;});
  const panel=document.getElementById('evalCritTotalResult');
  if(panel){panel.className='crit-total-panel '+(total>=70?'eval-auto-pass':'eval-auto-risk');panel.innerHTML=`<strong>Puntaje total autoevaluado: ${total}/100</strong><br><em>Compara siempre tus respuestas con la Pauta antes de anotar el puntaje de cada sección.</em>`;}
  const formKey='crit_'+(window._currentEvalCritForm||1);
  if(total>=70){if(!xpTracker.wgt.has(formKey)){xpTracker.wgt.add(formKey);pts(8);}showToast('🎯 La cifra sobre la mesa: '+total+'/100');}
  else showToast('🧮 Puntaje registrado: '+total+'/100. ¡Sigue practicando!');
}
function printEvalCrit(){
  if(!window._evalCritData){showToast('⚠️ Genera una prueba primero');return;}
  sfx('click');
  const forma=window._currentEvalCritForm||1;const d=window._evalCritData;
  const lines=(n)=>Array(n).fill('<div class="ln"></div>').join('');
  let s1=`<div class="sec-title"><span>I. La cifra sobre la mesa</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.kase.txt}</p>`;
  critCaseQuestions.forEach(q=>{s1+=`<p class="crit-print-q">${q}</p>${lines(1)}`;});
  let s2=`<div class="sec-title"><span>II. Corrige el error</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.err.txt}</p><p class="crit-print-q">Identifica dos errores y corrígelos con tus propias palabras:</p><p class="crit-print-q"><strong>Error 1:</strong></p>${lines(1)}<p class="crit-print-q"><strong>Error 2:</strong></p>${lines(1)}`;
  let s3=`<div class="sec-title"><span>III. Toma de decisiones bajo presión</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><p class="crit-print-scenario">${d.dec}</p><p class="crit-print-q">¿Qué mide exactamente esta cifra, de qué fuente y de qué año sale, y cuál es su horquilla? Nombra la auditoría que va al lado con su etiqueta, di si el titular tomó la punta o el centro, y separa lo que es dato de lo que es decisión, diciendo quién paga y en qué plazo.</p>${lines(2)}`;
  let s4=`<div class="sec-title"><span>IV. Comparación razonada</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div><div class="crit-compare-print-grid"><div class="crit-compare-print-box"><strong>Caso A:</strong> ${d.cmp.a}</div><div class="crit-compare-print-box"><strong>Caso B:</strong> ${d.cmp.b}</div></div><p class="crit-print-q">1. ¿Cuál de los dos se puede comprobar y cuál solo se puede repetir? 2. ¿Por qué no enseñan lo mismo a quien los lee?</p>${lines(2)}`;
  let ceTbl='<table class="crit-print-tbl"><tr><th>Causa</th><th>Efecto</th></tr>';
  d.causes.forEach(it=>{ceTbl+=`<tr><td>${it.cause}</td><td></td></tr>`;});
  d.effects.forEach(it=>{ceTbl+=`<tr><td></td><td>${it.effect}</td></tr>`;});
  ceTbl+='</table>';
  let s5=`<div class="sec-title"><span>V. Análisis de causas y efectos</span><div class="obt-row"><span class="obt-lbl">Obtenido:</span><span class="obt-line"></span><span class="obt-pct">de 20</span></div></div>${ceTbl}`;
  let pR='';
  pR+=`<div class="p-sec"><div class="p-ttl">I. Caso</div>${critCaseQuestions.map((q,i)=>`<div class="p-crit-line"><strong>${i+1}.</strong> ${critCaseGuides[i]}</div>`).join('')}</div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">II. Corrige el error</div><div class="p-crit-line"><strong>Error 1:</strong> ${d.err.g1}</div><div class="p-crit-line"><strong>Error 2:</strong> ${d.err.g2}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">III. Toma de decisiones</div><div class="p-crit-line">${critDecisionGuide}</div></div>`;
  pR+=`<div class="p-sec"><div class="p-ttl">IV. Comparación</div><div class="p-crit-line"><strong>Caso A:</strong> ${d.cmp.ga}</div><div class="p-crit-line"><strong>Caso B:</strong> ${d.cmp.gb}</div><div class="p-crit-line">${d.cmp.gr}</div></div>`;
  pR+=`<div class="p-sec" style="grid-column:1/-1;"><div class="p-ttl">V. Causas y efectos</div>${d.causes.map(it=>`<div class="p-crit-line"><strong>Causa:</strong> ${it.cause} → <strong>Efecto:</strong> ${it.guide}</div>`).join('')}${d.effects.map(it=>`<div class="p-crit-line"><strong>Efecto:</strong> ${it.effect} → <strong>Causa:</strong> ${it.guide}</div>`).join('')}</div>`;
  const doc=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>La cifra sobre la mesa Las dos facturas · Ruta del Expediente Dorado · Forma ${forma}</title><style>*{margin:0;padding:0;box-sizing:border-box;}body{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#111;background:#fff;padding:1mm 5mm;}.ph{margin-bottom:0.3rem;}.ph h2{font-size:11pt;font-weight:700;text-align:center;margin-bottom:0.2rem;}.ph-line{display:flex;align-items:baseline;gap:5px;margin-bottom:3px;}.ph-fill{flex:1;border-bottom:1px solid #555;min-height:12px;display:block;}.ph-m{display:inline-block;min-width:80px;border-bottom:1px solid #555;}.ph-s{display:inline-block;min-width:52px;border-bottom:1px solid #555;}.ph-xs{display:inline-block;min-width:36px;border-bottom:1px solid #555;}.ph-crit{font-size:9.5pt;text-align:center;color:#555;margin-top:0.1rem;}.sec-title{font-size:10.5pt;font-weight:700;padding:0.1rem 0.4rem;margin:0.2rem 0 0.1rem;display:flex;justify-content:space-between;align-items:center;border-left:4px solid #115e59;background:#f0fdfa;color:#115e59;}.obt-row{display:flex;align-items:baseline;gap:4px;font-size:9.5pt;font-weight:700;font-style:italic;color:#115e59;}.obt-lbl{white-space:nowrap;}.obt-line{display:inline-block;min-width:50px;border-bottom:1.5px solid #115e59;height:12px;}.obt-pct{white-space:nowrap;}.crit-print-scenario{font-size:10.5pt;background:#f0fdfa;border-left:3px solid #115e59;padding:0.2rem 0.5rem;margin:0.1rem 0 0.2rem;line-height:1.3;}.crit-print-q{font-size:10pt;font-weight:600;margin:0.15rem 0 0.08rem;line-height:1.25;}.ln{border-bottom:1px solid #111;min-height:12px;margin-bottom:2px;}.crit-compare-print-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.5rem;margin:0.15rem 0;}.crit-compare-print-box{font-size:9.5pt;background:#f0fdfa;border-radius:4px;padding:0.25rem 0.4rem;line-height:1.25;}.crit-print-tbl{width:100%;border-collapse:collapse;font-size:9.5pt;margin-top:0.15rem;}.crit-print-tbl th,.crit-print-tbl td{border:1px solid #999;padding:0.3rem 0.45rem;text-align:left;height:30px;vertical-align:middle;}.crit-print-tbl th{background:#f0fdfa;}.pauta-wrap{page-break-before:always;padding-top:0.4rem;}.p-head{border-bottom:2px solid #333;padding-bottom:0.3rem;margin-bottom:0.4rem;text-align:center;}.p-main{font-size:9.5pt;font-weight:700;}.p-sub{font-size:7pt;color:#c00;font-weight:700;margin:0.08rem 0;}.p-meta{font-size:7pt;color:#555;}.p-grid{display:grid;grid-template-columns:1fr 1fr;gap:0.4rem 0.9rem;}.p-sec{border:1px solid #ccc;border-radius:4px;padding:0.3rem 0.45rem;}.p-ttl{font-size:8pt;font-weight:700;border-bottom:1px solid #ddd;padding-bottom:0.1rem;margin-bottom:0.18rem;}.p-crit-line{font-size:7.5pt;color:#007a00;margin-bottom:0.18rem;line-height:1.35;}.total-row{display:flex;align-items:baseline;justify-content:flex-start;margin-left:20%;gap:7px;font-size:11pt;font-weight:700;font-style:italic;margin-top:0.2rem;padding:0.1rem 0;color:#115e59;}.total-row .obt-line{min-width:80px;border-bottom:1.5px solid #115e59;}.forma-tag{font-size:7pt;color:#555;border:1px solid #bbb;padding:1px 5px;border-radius:3px;background:white;}.print-foot{position:fixed;bottom:2mm;left:0;right:0;display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:7.5pt;color:#111;background:#fff;padding:1px 3px;}.pf-item{display:inline-flex;align-items:center;gap:4px;}.pf-line{display:inline-block;width:26mm;border-bottom:1px solid #333;}.pf-box{display:inline-block;width:3.4mm;height:3.4mm;border:1px solid #333;}@media print{@page{size:letter portrait;margin:12.7mm;}}</style></head><body><div class="ph"><h2>Evaluación Competencial · La cifra sobre la mesa · Las dos facturas · Ruta del Expediente Dorado · Etapa 4 · Estudio Mayor</h2><div class="ph-line"><strong>Nombre:</strong><span class="ph-fill">&nbsp;</span><strong>Fecha:</strong><span class="ph-m">&nbsp;</span></div><div class="ph-line"><strong>Institución:</strong><span class="ph-fill">&nbsp;</span><strong>Grado y Sección:</strong><span class="ph-s">&nbsp;</span><strong>Nº Lista:</strong><span class="ph-xs">&nbsp;</span></div><p class="ph-crit">Valor total: 100 puntos · 5 secciones de 20 puntos</p></div>${s1}${s2}${s3}${s4}${s5}<div class="total-row"><span>Total, obtenido</span><span class="obt-line"></span><span>de 100</span></div><div class="pauta-wrap"><div class="p-head"><div class="p-main">✅ PAUTA: La cifra sobre la mesa · Las dos facturas · Ruta del Expediente Dorado · Forma ${forma}</div><div class="p-sub">Documento exclusivo del docente · No distribuir al estudiante</div><div class="p-meta">Valor total: 100 pts | 5 secciones × 20 pts c/u, respuesta abierta, usar como guía de corrección</div></div><div class="p-grid">${pR}</div></div><div class="print-foot"><span class="pf-item"><strong>Nº de Evaluación temática realizada:</strong><span class="pf-line">&nbsp;</span></span><span class="pf-item"><strong>Evaluación con valor en el parcial</strong><span class="pf-box"></span></span><span class="pf-item"><strong>Evaluación solo de repaso</strong><span class="pf-box"></span></span><span class="forma-tag">Forma ${forma}</span></div></body></html>`;
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}

// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1958","icon":"📈","label":"Keeling empieza a medir","text":"<strong>Charles David Keeling</strong> instala su equipo en <strong>Mauna Loa</strong> y empieza a medir dióxido de carbono todos los días. La curva sube y baja con las estaciones y sube año tras año. Etiqueta: <strong>la medición más limpia que tiene este tema</strong>, y se cita por el método."},{"y":"2006","icon":"⏳","label":"La «Stern Review»","text":"<strong>Nicholas Stern</strong> publica un informe encargado por el gobierno británico donde usa una <strong>tasa de descuento muy baja</strong>: el futuro casi vale lo mismo que el presente, y de ahí sale actuar fuerte y ya. Etiqueta: <strong>informe oficial, y muy discutido</strong>."},{"y":"2009","icon":"🎲","label":"Weitzman y las colas","text":"<strong>Martin Weitzman</strong> sostiene que la discusión del promedio se queda corta: lo que manda son <strong>las colas gordas</strong>, la probabilidad pequeña de una catástrofe grande. Etiqueta: <strong>el giro teórico</strong> de este debate."},{"y":"2013","icon":"🔩","label":"Pindyck, el acero","text":"En el <strong>«Journal of Economic Literature»</strong>, <strong>Robert Pindyck</strong> critica desde dentro de la profesión los modelos que producen estas cifras: <strong>sus funciones de daño están elegidas casi arbitrariamente</strong>. Etiqueta: <strong>el acero</strong>, y se contesta en vez de esquivarse."},{"y":"2014","icon":"📕","label":"Piketty, y su auditoría","text":"Aparece en inglés <strong>«El capital en el siglo XXI»</strong>: cuando el capital rinde más de lo que crece la economía, lo heredado pesa más que lo trabajado. Ese mismo año, <strong>Chris Giles</strong>, del <strong>Financial Times</strong>, cuestiona parte de sus series y <strong>Piketty responde publicando sus datos</strong>."},{"y":"2015","icon":"🏠","label":"Rognlie mira la vivienda","text":"<strong>Matthew Rognlie</strong> muestra, en un trabajo de la <strong>Brookings Institution</strong>, que <strong>casi todo el aumento de la participación del capital viene de la vivienda</strong>. Etiqueta: <strong>la auditoría obligada</strong>. No derriba la tesis: cambia el remedio."},{"y":"2015","icon":"🌍","label":"El Acuerdo de París","text":"Se acuerda quedarse <strong>bien por debajo de 2 °C</strong> y perseguir <strong>1,5 °C</strong>. Etiqueta: <strong>decisión política, no resultado científico</strong>, y esa distinción es la mitad de la etapa."},{"y":"2016","icon":"🐘","label":"El elefante, y su objeción","text":"<strong>Milanović</strong> desarrolla en <strong>«Global Inequality»</strong> la curva que él y <strong>Lakner</strong> habían trazado: entre países bajó, dentro de los ricos subió. Ese mismo año, <strong>Adam Corlett</strong>, en la <strong>Resolution Foundation</strong>, muestra que <strong>su forma depende de qué países entren</strong>."},{"y":"2017","icon":"🎓","label":"Chetty mide la movilidad","text":"En <strong>«Science»</strong>, <strong>Raj Chetty</strong> y su equipo publican que del <strong>90 %</strong> de los estadounidenses nacidos en <strong>1940</strong> que superó a sus padres se pasó a cerca de <strong>la mitad</strong> entre los nacidos en <strong>1984</strong>. Etiqueta: <strong>medición de movilidad</strong>."},{"y":"2021","icon":"🌡️","label":"La horquilla del IPCC","text":"El <strong>sexto informe de evaluación</strong> estima la sensibilidad climática entre <strong>2,5 y 4 °C</strong>, con <strong>3 °C</strong> como mejor estimación, y el calentamiento ya ocurrido en torno a <strong>1,1 °C</strong>. Etiqueta: <strong>fuente oficial, y de las que publican su rango</strong>."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(prueba){sfx(prueba?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(prueba){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🌡️</span><span class="ms-text"><strong>Quedó anotada la cifra de pie:</strong> «el uno por ciento más rico tiene más <strong>riqueza neta</strong> que la mitad más pobre; riqueza neta es lo que se tiene menos lo que se debe, y por eso un graduado endeudado aparece más pobre que alguien sin deudas y sin tierra». Fuente y año al lado.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🧾</span><span class="ms-text"><strong>Y debajo, lo que no se puede olvidar:</strong> que el titular se lea mal <strong>no borra la concentración de la riqueza</strong>, que está medida por otras vías. Si lo que se quiere mostrar es concentración, sirven mejor <strong>las participaciones de ingreso y de riqueza publicadas con su metodología</strong>. Desarmar el titular es el principio del trabajo, no el final.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">📰</span><span class="ms-text"><strong>Quedó el titular tal cual:</strong> «el uno por ciento tiene más que la mitad del mundo». Es verdadero, viene de un informe serio y se comparte solo, que es justo el problema.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🪤</span><span class="ms-text"><strong>El costo llega en dos partes:</strong> quien lo lea se queda con un retrato que la cifra no sostiene, porque mide riqueza neta; y de camino queda enseñado que en esta casa <strong>una cifra se repite sin preguntar qué mide</strong>. Se tacha y se reescribe con la definición, la fuente y el año.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

// ===================== LABORATORIO DE CONCEPTOS =====================
const parteData={"desigualdad":{"nombre":"La factura de la desigualdad","icon":"💰","estructura":{"title":"Qué dice","info":"• Que la máquina reparte, y que ese reparto <strong>se puede medir</strong><br>• Su dificultad no es de datos: es <strong>de definición</strong><br>• <strong>Piketty (2014)</strong>: cuando el capital rinde más que el crecimiento, lo heredado pesa más"},"funcion":{"title":"Cómo se reconoce","info":"• Se piden las <strong>cuatro decisiones</strong> antes de aceptar la cifra<br>• Qué (ingreso o riqueza), cuándo (antes o después de impuestos)<br>• Entre quiénes (dentro o entre países) y con qué número (índice o participaciones)"},"enfermedades":{"title":"Dónde se cae","info":"• Confundir <strong>riqueza neta con pobreza</strong>, que es el error del titular famoso<br>• Citar a <strong>Piketty sin Rognlie</strong>, que es media cita<br>• Y usar <strong>«siempre»</strong> sobre algo que se mide, que es renunciar a medirlo"},"cuidados":{"title":"En esta casa","info":"• <strong>Piketty (2014) y Rognlie (2015) entran juntos</strong>, al lado y no debajo<br>• Con el episodio de <strong>Giles (2014)</strong> y la respuesta con datos<br>• Y toda cifra que se publique aquí lleva <strong>fuente y año</strong>"}},"elefante":{"nombre":"La curva del elefante","icon":"🐘","estructura":{"title":"Qué dice","info":"• Ordena a <strong>toda la humanidad</strong> de más pobre a más rica, entre <strong>1988 y 2008</strong><br>• El <strong>lomo</strong>: cientos de millones que salieron de la pobreza<br>• El <strong>cuello hundido</strong>: los trabajadores de los países ricos. La <strong>trompa</strong>: el 1 %"},"funcion":{"title":"Cómo se reconoce","info":"• Cuando alguien dice «la desigualdad subió» y otro «bajó», y <strong>los dos tienen razón</strong><br>• Uno mira <strong>dentro</strong> de un país y el otro <strong>entre</strong> países<br>• De <strong>Lakner y Milanović</strong>, desarrollada en <strong>«Global Inequality» (2016)</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• Contar <strong>media película</strong>: solo el lomo, o solo el cuello hundido<br>• Tratar el dibujo como <strong>intocable</strong>, cuando tiene objeción publicada<br>• Y olvidar que <strong>el periodo importa</strong>: es de 1988 a 2008, no de siempre"},"cuidados":{"title":"En esta casa","info":"• La curva entra <strong>con la objeción de Corlett (2016)</strong> encima, siempre<br>• Se dice que <strong>el hundimiento sigue existiendo, pero es más pequeño</strong><br>• Y se usa para lo que sirve: <strong>incomodar a los dos estantes con el mismo trazo</strong>"}},"clima":{"nombre":"La factura del clima","icon":"🌡️","estructura":{"title":"Qué dice","info":"• Lo medido es sólido: la serie de <strong>Keeling desde 1958</strong> y <strong>1,1 °C</strong> ya ocurridos<br>• Lo incierto es <strong>cuánto calienta</strong>: de <strong>2,5 a 4 °C</strong>, con <strong>3 °C</strong> como mejor estimación<br>• Y lo acordado es político: <strong>París, 2015</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• Se busca la <strong>horquilla</strong> antes que la conclusión<br>• Se separa <strong>lo medido</strong> de <strong>lo proyectado</strong> y de <strong>lo decidido</strong><br>• Y se usa la <strong>identidad de Kaya</strong> para ver por dónde empuja cada propuesta"},"enfermedades":{"title":"Dónde se cae","info":"• <strong>Escoger la punta del rango</strong>, en cualquiera de las dos direcciones<br>• Saltar de <strong>un evento suelto</strong> a la causa sin ciencia de atribución<br>• Y mezclar <strong>emisiones territoriales con emisiones de consumo</strong>"},"cuidados":{"title":"En esta casa","info":"• La horquilla se escribe <strong>entera y con su mejor estimación</strong><br>• Lo que es <strong>decisión política</strong> se dice que lo es, empezando por París<br>• Y los pleitos del patio entran <strong>como categoría, no con nombre propio</strong>"}},"descuento":{"nombre":"La tasa de descuento","icon":"⏳","estructura":{"title":"Qué dice","info":"• <strong>Cuánto vale hoy el bienestar de alguien que todavía no ha nacido</strong><br>• Es un número, y lo que lo decide <strong>no es un dato físico sino una posición moral</strong><br>• De ahí sale el ritmo: <strong>fuerte y ya</strong> o <strong>gradual</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• Cuando dos personas miran <strong>los mismos datos</strong> y proponen cosas distintas<br>• <strong>Stern (2006)</strong> la puso muy baja; <strong>Nordhaus</strong>, más alta<br>• Y en la cocina: <strong>arreglar el techo este año o el próximo</strong>"},"enfermedades":{"title":"Dónde se cae","info":"• Presentarla como <strong>un resultado científico</strong>, que no lo es<br>• Y del otro lado, negar el dato físico <strong>porque la decisión no gusta</strong><br>• Olvidar a <strong>Weitzman (2009)</strong>: lo que decide puede ser <strong>la cola</strong> y no el promedio"},"cuidados":{"title":"En esta casa","info":"• <strong>Stern y Nordhaus entran juntos</strong>, y se dice que discrepan en valores<br>• Con <strong>el acero de Pindyck (2013)</strong> al lado, que viene de dentro de la profesión<br>• Y con la regla que atraviesa la ruta: <strong>lo que es decisión se dice que es decisión</strong>"}}};
let labParte='desigualdad',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

