const lectComprensionBank=[{"t":"Borges","q":"¿Qué llevaba el abuelo del narrador durante cuarenta años, y con qué instrumentos?","o":["a) Un libro de cuentas de la finca","b) Un registro diario de la lluvia, con un embudo de latón y una probeta de farmacia","c) Un herbario de la región","d) Un diario personal"],"c":1},{"t":"Borges","q":"Al sumar las columnas del abuelo, ¿qué descubrió el narrador sobre la lluvia de aquel valle?","o":["a) Que llovió mucho menos que antes","b) Que llovió más que nunca","c) Que llovió igual, pero peor repartido: menos días de lluvia y más lluvia por día","d) Que los datos no servían para nada"],"c":2},{"t":"Borges","q":"¿Qué le pasó al narrador cuando vio dos periódicos citar el mismo informe del IPCC?","o":["a) Vio que uno alarmaba y otro tranquilizaba, y que cada uno había elegido una punta del rango","b) Descubrió que el informe estaba mal","c) Comprobó que los dos mentían","d) Dejó de leer periódicos"],"c":0},{"t":"Borges","q":"Según el cuento, ¿por qué Piketty se parece al abuelo del narrador?","o":["a) Porque también medía la lluvia","b) Porque escribió un libro muy largo","c) Porque publicó los datos con los que se le podía refutar","d) Porque nunca opinaba"],"c":2},{"t":"Borges","q":"¿Qué frase resume la regla que el narrador anota para sí mismo sobre los rangos?","o":["a) Que la horquilla no es la debilidad del dato, sino la parte que dice cuánto sabemos","b) Que los rangos se deben convertir en una sola cifra","c) Que sin certeza no se puede decidir","d) Que los científicos exageran"],"c":0},{"t":"Cervantes","q":"¿Cómo descubrió Sancho el engaño del báculo?","o":["a) Porque advirtió que el juramento era verdadero solo mientras el otro tuviera la caña, y mandó quebrarla","b) Porque el viejo confesó","c) Porque contó las monedas del acreedor","d) Porque el mayordomo se lo dijo"],"c":0},{"t":"Cervantes","q":"Según Sancho, ¿dónde estaba la mentira del viejo?","o":["a) En las palabras, que eran falsas","b) En el juramento, que fue mal hecho","c) En el báculo, que no era suyo","d) No en las palabras, que eran ciertas, sino en lo que dejaban entender"],"c":3},{"t":"Cervantes","q":"¿Por qué no concordaban los dos memoriales de los contadores de la ínsula?","o":["a) Porque uno había sumado mal","b) Porque uno contaba lo que entra cada mes y el otro lo que cada casa tiene guardado quitando lo que debe","c) Porque uno mentía a propósito","d) Porque faltaban papeles"],"c":1},{"t":"Cervantes","q":"¿Qué manda Sancho que se escriba desde entonces en la cabeza de cada memorial?","o":["a) El nombre del contador","b) La fecha y la hora","c) El sello del gobernador","d) Qué cosa es la que se cuenta, con letra gruesa"],"c":3},{"t":"Cervantes","q":"¿De quién se fía más Sancho: del que da un número entre dos cantidades o del que clava una cifra exacta?","o":["a) Del que clava la cifra exacta, porque parece más sabio","b) De ninguno de los dos","c) Del que dice «entre cien y ciento cincuenta», porque también le está diciendo lo que no sabe","d) Del que trae más papeles"],"c":2},{"t":"Harari","q":"Según el ensayo, ¿qué es lo verdaderamente nuevo en la historia de la especie, y desde hace cuánto?","o":["a) La agricultura, desde hace milenios","b) Que aprendimos a medirnos, y tiene apenas unos siglos","c) El dinero, desde hace siglos","d) La escritura, desde hace cinco mil años"],"c":1},{"t":"Harari","q":"¿Qué dice el ensayo que significa de verdad un rango publicado por los científicos?","o":["a) Que se sabe con precisión cuánto no se sabe","b) Que no se pusieron de acuerdo","c) Que faltan mediciones","d) Que el tema es político"],"c":0},{"t":"Harari","q":"¿Cuál es, según el ensayo, la parte mejor de la historia de Piketty y que casi nunca se cuenta?","o":["a) Que vendió muchos ejemplares","b) Que escribió en francés","c) Que nadie pudo discutirlo","d) Que lo auditaron: Rognlie en 2015 y Giles en 2014, y él respondió publicando sus datos"],"c":3},{"t":"Harari","q":"El resultado de Chetty y su equipo publicado en «Science» en 2017 dice que…","o":["a) La desigualdad bajó en Estados Unidos","b) Del 90 % de los nacidos en 1940 que superó a sus padres se pasó a cerca de la mitad entre los nacidos en 1984","c) La movilidad no se puede medir","d) Todos los hijos ganan más que sus padres"],"c":1},{"t":"Harari","q":"¿Cuáles son las tres preguntas que el ensayo propone para cualquier número?","o":["a) Quién lo dice, cuándo y por qué","b) Si es grande, si es nuevo y si asusta","c) Qué mide exactamente, de qué fuente y año sale, y entre qué números anda","d) Si conviene, si convence y si se puede compartir"],"c":2},{"t":"Entrevista","q":"¿Con qué regla de la casa se sienta Piketty a la entrevista?","o":["a) Con la de no hablar de sus críticos","b) Con la de que ninguna cifra entra sin decir qué mide, de dónde sale y entre qué números anda","c) Con la de citar solo su propio libro","d) Con la de no dar números en televisión"],"c":1},{"t":"Entrevista","q":"Según Piketty, ¿qué efecto tiene la objeción de Rognlie (2015) sobre su libro?","o":["a) Lo obliga a retirar la tesis entera","b) No tiene ninguna importancia","c) Demuestra que sus datos estaban inventados","d) No derrumba la tesis, pero cambia el remedio: si casi todo viene de la vivienda, se habla de suelo, ciudades y alquileres"],"c":3},{"t":"Entrevista","q":"¿Qué dice Piketty que aprendió del episodio con Chris Giles y el «Financial Times» (2014)?","o":["a) Que la única autoridad que vale es la que se puede auditar, y por eso publicó sus tablas","b) Que no hay que responderle a los periodistas","c) Que los periódicos siempre se equivocan","d) Que era mejor retirar el libro de las librerías"],"c":0},{"t":"Entrevista","q":"¿Cuáles son las cuatro decisiones que Piketty pide tomar antes de aceptar una cifra de desigualdad?","o":["a) Quién la dice, cuándo, dónde y por qué","b) Si es grande, si es nueva, si asusta y si conviene","c) Qué se mide, cuándo se mide, entre quiénes y con qué número","d) La fuente, el titular, la foto y el pie de página"],"c":2},{"t":"Entrevista","q":"Sobre el titular del uno por ciento, Piketty responde que…","o":["a) Miente de principio a fin","b) Es exacto y no hay nada que discutir","c) Lo escribió un enemigo suyo","d) No miente: deja entender; y descubrir el truco de la resta no borra la concentración, que está medida por varias vías"],"c":3},{"t":"Quintero y Gala","q":"¿Qué le trae Quintero a Gala al empezar la conversación?","o":["a) Un libro de poemas","b) Una carta de un oyente","c) Dos facturas: la del planeta que se calienta y la de los hombres que se reparten mal lo que tienen","d) Un mapa de Córdoba"],"c":2},{"t":"Quintero y Gala","q":"Para Gala, la horquilla del informe del clima (entre 2,5 y 4 grados) es…","o":["a) Una reverencia: quien da el rango dice lo que sabe y también cuánto ignora","b) Una prueba de que los científicos no se ponen de acuerdo","c) Un error de imprenta","d) Una manera de asustar a la gente"],"c":0},{"t":"Quintero y Gala","q":"¿Qué dato trae Quintero sobre el dibujo del elefante?","o":["a) Que lo pintó un artista cordobés","b) Que mide la temperatura del planeta","c) Que se publicó en la revista «Science»","d) Que Lakner y Milanović midieron quién ganó entre 1988 y 2008: el lomo de Asia, el hueco de los obreros ricos y la trompa del uno por ciento"],"c":3},{"t":"Quintero y Gala","q":"¿En qué convierte Gala el resultado de Chetty («Science», 2017)?","o":["a) En un chiste sobre los ricos","b) En una imagen: la promesa de que el hijo vivirá mejor es la inmortalidad de los pobres, y ese número dice que se está muriendo","c) En una acusación contra los maestros","d) En una razón para no medir nada"],"c":1},{"t":"Quintero y Gala","q":"¿Cuál es la regla final que Gala le regala a Quintero?","o":["a) No creer en ningún número","b) Pedirle a cada cifra sus tres apellidos: qué mide, de dónde viene y entre qué números anda","c) Leer solo los periódicos de la mañana","d) Preguntarle siempre a un experto"],"c":1}];
const lectCompletarBank=[{"t":"las cinco","q":"Charles David Keeling empezó a medir dióxido de carbono en Mauna Loa en ___.","a":"1958"},{"t":"las cinco","q":"El sexto informe del IPCC, de ___, estima la sensibilidad climática entre 2,5 y 4 °C.","a":"2021"},{"t":"las cinco","q":"La mejor estimación de ese rango es de ___ grados.","a":"3"},{"t":"Borges","q":"Thomas Piketty publicó en inglés su libro sobre el capital en ___.","a":"2014"},{"t":"Borges","q":"Matthew Rognlie mostró en ___ que casi todo el aumento venía de la vivienda.","a":"2015"},{"t":"Harari","q":"Adam Corlett publicó su objeción a la curva del elefante en ___.","a":"2016"},{"t":"Harari","q":"Raj Chetty y su equipo publicaron su medición de movilidad en la revista ___.","a":"Science"},{"t":"las cinco","q":"Nicholas Stern publicó su informe en ___.","a":"2006"},{"t":"las cinco","q":"William Nordhaus recibió el Nobel de Economía en ___.","a":"2018"},{"t":"Cervantes","q":"Sancho mandó quebrar el ___ para hallar dentro los diez escudos.","a":"báculo"}];
const lectAnalisisBank=[{"q":"1. Las tres primeras lecturas llegan a la misma disciplina por tres puertas. Explica qué hace cada voz que las otras dos no pueden hacer, y qué se perdería leyendo solo una.","guia":"El cuento convierte el método en una herencia y por eso lo vuelve memorable: ochenta y siete cuadernos de hule negro, un hombre que durante cuarenta años prefirió medir a tener razón, y el hallazgo de que en aquel valle no llovió menos sino peor repartido, cosa que ninguna sobremesa habría podido establecer. Esa forma enseña algo que una tabla no puede: que anotar es un acto de humildad y también el único camino para saber. El capítulo lo vuelve escena, risa y refrán, y llega a donde el argumento no llega: el báculo con los escudos dentro deja pegada de por vida la idea de que se puede mentir con verdades, y los dos contadores que no concuerdan enseñan en cuatro líneas lo que aquí se llama la definición. El ensayo pone la escala de especie y encadena la erudición con sus años, que es lo que permite comprobar. Leyendo solo el cuento se tendría método sin fuentes; solo el capítulo, astucia sin datos; solo el ensayo, datos sin ninguna imagen que los fije. Las tres juntas dan lo mismo por tres caminos, y por eso la casa las escribe así."},{"q":"2. El cuento dice que «una memoria es un dato y una serie es una prueba». Explica esa frase con el caso del pozo de la aldea y con el de la lluvia del valle.","guia":"Una memoria es un dato porque no es mentira ni es despreciable: la gente mayor que recuerda que el pozo aguantaba todo el verano está aportando información real sobre lo que vivió. Lo que no puede hacer una memoria es promediar, porque la cabeza no guarda promedios sino sustos, y por eso todo el mundo recuerda el año que se secó y no los tres que estuvieron normales. Una serie es una prueba porque sí promedia y porque permite separar variabilidad de tendencia, que es la distinción que decide estos casos: un año malo no es una tendencia, y una tendencia no se ve sin varios años anotados. En el cuento eso se muestra con elegancia, porque el resultado no le da la razón a nadie del todo: los viejos decían que llovía más y en realidad llovía igual pero peor repartido, con menos días de lluvia y más lluvia por día. Tenían razón en lo que sentían y no en lo que afirmaban, y eso solo se pudo saber porque hubo cuadernos. La consecuencia práctica para esta casa es directa y barata: anotar la fecha en que se seca el pozo, año tras año, vale más que diez discusiones."},{"q":"3. Sancho dice que la mentira del viejo no estaba en las palabras sino en lo que las palabras dejaban entender. Aplica esa idea al titular del uno por ciento.","guia":"El viejo juró que había devuelto los diez escudos de su mano a la del otro, y era verdad en el instante exacto del juramento, porque acababa de darle el báculo que los llevaba dentro. Cada palabra era cierta y el resultado era un engaño completo. El titular del uno por ciento funciona igual: la cifra está bien calculada y mide riqueza neta, es decir lo que uno tiene menos lo que debe, de modo que la afirmación es correcta. El engaño está en lo que deja entender, porque con esa vara un recién graduado con un préstamo grande aparece más pobre que un campesino sin deudas y sin tierra, y el retrato que se forma quien escucha no corresponde a la realidad que quería describirse. La lección de método es que no basta con preguntar si una cifra es verdadera, hay que preguntar qué mide y qué imagen deja. Y la lección honrada, que Sancho también habría aceptado, es que descubrir el truco del báculo no borra la deuda: que el titular se lea mal no elimina la concentración de la riqueza, que está medida por otras vías."},{"q":"4. Los dos contadores de la ínsula tienen razón y dicen cosas contrarias. Explica el episodio y relaciónalo con las cuatro decisiones de esta etapa.","guia":"Uno cuenta lo que entra en la ínsula cada mes y el otro lo que cada casa tiene guardado quitando lo que debe, de manera que el primero mide un flujo y el segundo un patrimonio. Los dos suman bien y llegan a conclusiones opuestas sobre si la ínsula está más rica o más pobre, y Sancho no le da la razón a ninguno: manda que cada memorial escriba arriba, con letra gruesa, qué cosa es la que cuenta. Eso es exactamente la primera de las cuatro decisiones de esta etapa, la de qué se mide, ingreso o riqueza. Las otras tres funcionan igual de bien en la ínsula: cuándo se mide, es decir antes o después de lo que el gobierno quita y da; entre quiénes, dentro de la ínsula o comparándola con las de al lado; y con qué número, un índice que resume todo en una cifra o participaciones que dicen cuánto se lleva cada tramo. Ninguna de esas decisiones es tramposa, y ahí está el detalle importante: el problema no son los contadores deshonestos, son los memoriales sin encabezado. Por eso la regla de Sancho es de procedimiento y no de moral, y por eso funciona."},{"q":"5. Sancho dice que se fía más del que le da un rango que del que le clava un número exacto. Explica por qué, y por qué al público le pasa lo contrario.","guia":"Se fía más porque el que dice «entre cien y ciento cincuenta fanegas» le está dando dos informaciones en vez de una: lo que sabe y, sobre todo, cuánto no sabe, y con las dos se puede gobernar, que es lo que él necesita. El que clava ciento veinticuatro sin pestañear le está ocultando la segunda, y como nadie puede tener esa precisión, lo que le está entregando es su parecer vestido de cuenta. Al público le pasa lo contrario por dos razones. La primera es práctica: un número redondo se recuerda, se repite y se comparte, y una horquilla no. La segunda es psicológica: la incertidumbre incomoda, y quien la declara parece menos competente que quien no la declara, aunque sea al revés. Eso explica el modo de fallar propio de esta etapa, que es escoger la punta del rango: quien quiere convencer sabe que el extremo funciona mejor que el centro, y lo toma. La defensa es la disciplina de Sancho llevada a la cocina: preferir la fuente que publica su rango, y desconfiar por sistema del número redondo sin fuente."},{"q":"6. Explica por qué la casa insiste en que Piketty se cite junto a Rognlie y al episodio del «Financial Times», y qué enseña eso sobre cómo se discute bien.","guia":"Porque una obra tan influyente y tan discutida no se puede citar por la mitad sin faltar a la regla del Estudio Mayor, que rige toda esta ruta y que ya se aplicó en las etapas anteriores con Coase y con Titmuss. Piketty sostuvo en 2014 que cuando el capital rinde más de lo que crece la economía, lo heredado pesa más que lo trabajado. Matthew Rognlie mostró en 2015 que casi todo el aumento de la participación del capital venía de la vivienda y no del capital productivo, lo cual no derriba la tesis pero cambia qué habría que hacer con ella, que es la clase de objeción más útil que existe. Y Chris Giles, del Financial Times, cuestionó en 2014 parte de sus series de riqueza. Lo que enseña el episodio es la conducta que vino después: Piketty respondió públicamente y publicó sus datos. Un autor que pone a disposición los números con los que se le puede refutar es más fiable que uno que solo publica conclusiones, y esa es la vara con la que esta casa quiere ser medida cuando publica sus propias cifras."},{"q":"7. El ensayo dice que la discusión seria sobre el clima no es sobre el termómetro. Explica de qué es, y por qué eso cambia la manera de discutir.","guia":"Es sobre cuánto vale hoy el bienestar de alguien que todavía no ha nacido, que es lo que técnicamente se llama tasa de descuento. Nicholas Stern, en su informe de 2006, usó una tasa muy baja, con lo cual el futuro pesa casi como el presente y la conclusión es actuar con fuerza y de inmediato. William Nordhaus, Nobel de Economía en 2018, usó una tasa más alta, tomada de cómo la gente descuenta realmente, y su conclusión es una senda más gradual. Los dos miran los mismos datos físicos, y por eso llamarlos negacionista o alarmista es no haber entendido de qué hablan. Que la discusión sea de valores y no de datos cambia tres cosas. Primero, nadie puede ganarla apelando a la autoridad científica, porque la ciencia no fija esa tasa. Segundo, hay que argumentar moralmente en voz alta, que es incómodo y honrado. Y tercero, la discusión deja de ser inaccesible: es la misma pregunta que se hace una familia cuando decide si arregla el techo este año o el próximo, y en esa forma cualquiera puede opinar con sentido."},{"q":"8. Weitzman y Pindyck aparecen en las tres primeras lecturas como incomodidades. Explica qué dice cada uno y por qué esta casa los incluye en vez de dejarlos fuera.","guia":"Weitzman sostuvo en 2009 que la discusión centrada en el promedio se queda corta, porque lo que debería pesar en una decisión son las colas: la probabilidad pequeña de una catástrofe grande e irreversible. Eso cambia la pregunta de cuánto va a calentar a cuánto pagaríamos por evitar lo irreparable, que es como se razona cuando uno compra un seguro. Pindyck escribió en 2013, en el Journal of Economic Literature, que los modelos integrados con los que se calculan los costos del clima tienen funciones de daño elegidas de manera casi arbitraria y aparentan una precisión que no tienen. Los dos incomodan, y en direcciones distintas: uno empuja a actuar más de lo que sugiere el promedio y el otro quita autoridad a los números con los que se decide. La casa los incluye porque la regla del acero se aplica siempre y no solo cuando conviene, y porque quien no conoce las objeciones a su propia posición no la está defendiendo, la está repitiendo. Y la respuesta que se da es la misma disciplina de la ruta: si el modelo no es preciso, se dice, y se decide igual, porque no decidir también es una decisión con factura."},{"q":"9. Explica el error propio de esta etapa y por qué la casa insiste en que desarmar un titular es el principio del trabajo y no el final.","guia":"El error propio es escoger la punta del rango que conviene y contarla como si fuera el número. Se reconoce en tres señales: la cifra aparece sin horquilla, no se dice qué mide exactamente, y no se dice de qué fuente y de qué año sale. Lo que hace a este error tan interesante es que lo cometen los dos bandos con el mismo informe, porque con una horquilla de 2,5 a 4 °C se puede alarmar y tranquilizar sin decir una sola falsedad. Ahora bien, quien aprende a detectarlo cae inmediatamente en el error simétrico, que es el más cómodo de todos: creer que porque el titular estaba mal contado el problema no existe. Eso es falso en las dos facturas. Que la cifra del uno por ciento se lea mal no borra la concentración de la riqueza, que está medida por otras vías; que alguien exagere con el clima no baja la raya del termómetro ni acorta la serie de Keeling. Por eso la casa insiste: desarmar una cifra mal contada es el primer paso, y el trabajo consiste en poner la cifra buena en su lugar, con su definición, su fuente y su rango."},{"q":"10. Los cinco textos llevan la etiqueta de ejercicio de estilo de la casa. Explica por qué esa etiqueta pertenece al temario de esta etapa en particular, y qué pasaría si se quitara.","guia":"Porque esta etapa se estudia entera sobre la diferencia entre una afirmación verdadera y una afirmación bien puesta de pie, y un pastiche sin declarar es exactamente el caso del báculo: cada frase del texto puede ser cierta y el conjunto engañar, porque el lector cree estar recibiendo la autoridad de Borges, de Cervantes o de Harari cuando detrás hay una casa que escribe misiones para sus hijas. Enseñar a pedir la fuente de cada cifra y firmar con una voz prestada sería la contradicción más rápida posible. Hay además una razón técnica que es el contenido mismo: la etiqueta funciona como el encabezado que Sancho manda escribir con letra gruesa en cada memorial, el renglón que dice qué cosa es esto. Si se quitara pasarían dos cosas comprobables. La primera, que alguien citaría a Piketty, al IPCC o a Chetty a través de una frase que ninguno escribió, con lo cual la casa estaría produciendo justamente la cifra sin fuente que su propia etapa enseña a cazar. La segunda, que la lección quedaría desmentida por el ejemplo, que es la forma más eficaz de no enseñar nada."}];
const xpLect={c:new Set(),f:new Set()};

/* ---------- I. Comprensión lectora ---------- */
let lcIdx=0,lcSel=-1,lcDone=false;
function showLectC(){const cont=document.getElementById('lcQ');if(!cont)return;if(lcIdx>=lectComprensionBank.length){cont.textContent='🎉 ¡Comprensión lectora completada!';document.getElementById('lcOpts').innerHTML='';document.getElementById('lcProg').textContent='Las '+lectComprensionBank.length+' preguntas respondidas';unlockAchievement('lect_master');return;}const q=lectComprensionBank[lcIdx];document.getElementById('lcProg').textContent='Pregunta '+(lcIdx+1)+' de '+lectComprensionBank.length+' · '+q.t;cont.textContent=q.q;const opts=document.getElementById('lcOpts');opts.innerHTML='';lcSel=-1;lcDone=false;q.o.forEach((o,i)=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=o;b.onclick=()=>{if(lcDone)return;opts.querySelectorAll('.qz-opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');lcSel=i;sfx('click');};opts.appendChild(b);});}
function checkLectC(){if(lcIdx>=lectComprensionBank.length)return;if(lcSel<0)return fb('fbLC','Selecciona una respuesta.',false);lcDone=true;const opts=document.querySelectorAll('#lcOpts .qz-opt');if(lcSel===lectComprensionBank[lcIdx].c){opts[lcSel].classList.add('correct');fb('fbLC','¡Correcto! +2 XP',true);if(!xpLect.c.has(lcIdx)){xpLect.c.add(lcIdx);pts(2);}sfx('ok');}else{opts[lcSel].classList.add('wrong');opts[lectComprensionBank[lcIdx].c].classList.add('correct');fb('fbLC','Incorrecto. Vuelve al texto: la respuesta está ahí.',false);sfx('no');}setTimeout(()=>{lcIdx++;showLectC();},1700);}
function resetLectC(){sfx('click');lcIdx=0;showLectC();document.getElementById('fbLC').classList.remove('show');}

/* ---------- II. Completar ---------- */
let lfIdx=0;
function showLectF(){const cont=document.getElementById('lfQ');if(!cont)return;if(lfIdx>=lectCompletarBank.length){cont.innerHTML='🎉 ¡Las diez oraciones completadas!';document.getElementById('lfProg').textContent='Terminado';const inp=document.getElementById('lfInput');if(inp)inp.style.display='none';return;}const d=lectCompletarBank[lfIdx];document.getElementById('lfProg').textContent='Oración '+(lfIdx+1)+' de '+lectCompletarBank.length+' · '+d.t;cont.innerHTML=d.q.replace('___','<span class="blank">___</span>');const inp=document.getElementById('lfInput');if(inp){inp.style.display='';inp.value='';inp.classList.remove('eval-input-ok','eval-input-no');}}
function checkLectF(){if(lfIdx>=lectCompletarBank.length)return;const inp=document.getElementById('lfInput');const d=lectCompletarBank[lfIdx];if(!inp.value.trim())return fb('fbLF','Escribe tu respuesta.',false);const ok=isCpCorrect(inp.value,d.a);inp.classList.toggle('eval-input-ok',ok);inp.classList.toggle('eval-input-no',!ok);if(ok){fb('fbLF','¡Correcto! +2 XP',true);if(!xpLect.f.has(lfIdx)){xpLect.f.add(lfIdx);pts(2);}sfx('ok');}else{fb('fbLF','Todavía no. La respuesta esperada era: '+d.a,false);sfx('no');}setTimeout(()=>{lfIdx++;showLectF();document.getElementById('fbLF').classList.remove('show');},1900);}
function resetLectF(){sfx('click');lfIdx=0;showLectF();document.getElementById('fbLF').classList.remove('show');}

/* ---------- III. Análisis complejo ---------- */
let laIdx=0,laPautaVisible=false;
function showLectA(){const cont=document.getElementById('laQ');if(!cont)return;const d=lectAnalisisBank[laIdx];document.getElementById('laProg').textContent='Pregunta '+(laIdx+1)+' de '+lectAnalisisBank.length;cont.textContent=d.q;const p=document.getElementById('laPauta');p.innerHTML='<strong>Pauta:</strong> '+d.guia;p.style.display=laPautaVisible?'block':'none';document.getElementById('laTA').value='';}
function nextLectA(){sfx('click');laIdx=(laIdx+1)%lectAnalisisBank.length;showLectA();}
function prevLectA(){sfx('click');laIdx=(laIdx-1+lectAnalisisBank.length)%lectAnalisisBank.length;showLectA();}
function toggleLectAPauta(){sfx('click');laPautaVisible=!laPautaVisible;const p=document.getElementById('laPauta');p.style.display=laPautaVisible?'block':'none';const b=document.getElementById('btnLectAPauta');if(b)b.textContent=laPautaVisible?'🙈 Ocultar pauta':'👁 Ver pauta';}

/* ---------- impresión: cada lectura por separado ---------- */
// La etiqueta del estatus viaja SIEMPRE con el texto impreso: una hoja
// suelta con un pastiche sin declarar es exactamente la fuente inflada que
// el Estudio Mayor enseña a cazar.
const LECTURAS_IMPR={
  borges:{titulo:'El hombre que midió la lluvia',tipo:'Cuento, a la manera de Jorge Luis Borges'},
  cervantes:{titulo:'Del pleito del báculo, y de lo que Sancho sentenció sobre las cuentas que dicen verdad y engañan',tipo:'Capítulo, a la manera de Miguel de Cervantes Saavedra'},
  harari:{titulo:'La especie que aprendió a medirse',tipo:'Ensayo, a la manera de Yuval Noah Harari'},
  // Las dos entrevistas llevan una etiqueta extra (ficcion): son personas
  // reales en un encuentro que nunca ocurrió, y eso tiene que viajar impreso
  // con la hoja, porque una entrevista suelta sin esa línea parecería real.
  entrevista:{titulo:'El economista que enseñó sus cuadernos',tipo:'Entrevista imaginada con Thomas Piketty, a la manera de Carmen Aristegui',
    ficcion:'<strong>Además, esta pieza es una entrevista IMAGINADA: el encuentro nunca ocurrió.</strong> Las personas son reales, y toda obra, fecha y cifra que se les pone en la boca es real y comprobable; lo único inventado es la conversación.'},
  gala:{titulo:'Los números de la noche',tipo:'El Loco de la Colina: Jesús Quintero conversa con Antonio Gala (conversación imaginada)',
    ficcion:'<strong>Además, esta pieza es una conversación IMAGINADA: el encuentro nunca ocurrió.</strong> Quintero y Gala son reales y se entrevistaron varias veces en la realidad; sus voces se imitan en homenaje, y todo dato citado dentro es real y comprobable.'},
};
function _hojaImpresa(titulo,cuerpo,pieExtra){
  return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${titulo} · Las dos facturas · F.A.R.O.</title><style>
@page{size:letter;margin:16mm 15mm;}
*{margin:0;padding:0;box-sizing:border-box;}
body{font-family:Georgia,'Times New Roman',serif;font-size:11.5pt;line-height:1.55;color:#111;background:#fff;}
h1{font-family:Arial,Helvetica,sans-serif;font-size:15pt;color:#042f2e;margin-bottom:2mm;line-height:1.2;}
.tipo{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;color:#555;margin-bottom:3mm;}
.ruta{font-family:Arial,Helvetica,sans-serif;font-size:9pt;color:#115e59;border-bottom:1.5pt solid #115e59;padding-bottom:1.5mm;margin-bottom:3mm;display:flex;justify-content:space-between;gap:6mm;}
.etiqueta{border:1.2pt solid #115e59;background:#f0fdfa;border-radius:2mm;padding:2.5mm 3mm;font-family:Arial,Helvetica,sans-serif;font-size:9pt;line-height:1.4;margin-bottom:4mm;}
.idline{font-family:Arial,Helvetica,sans-serif;font-size:9pt;display:flex;gap:4mm;margin-bottom:3mm;}
.idline span.r{flex:1;border-bottom:0.8pt solid #666;}
p.t{text-align:justify;margin-bottom:2.6mm;text-indent:6mm;}
p.t:first-of-type{text-indent:0;}
h2{font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#042f2e;margin:4mm 0 2mm;}
.sec{font-family:Arial,Helvetica,sans-serif;font-size:10.5pt;font-weight:700;color:#115e59;background:#f0fdfa;border-left:3pt solid #115e59;padding:1.2mm 2.5mm;margin:4mm 0 2mm;}
.q{font-family:Arial,Helvetica,sans-serif;font-size:10pt;margin:2mm 0 1mm;}
.q .n{font-weight:700;color:#115e59;}
.op{font-family:Arial,Helvetica,sans-serif;font-size:9.5pt;margin-left:7mm;}
.ln{border-bottom:0.8pt solid #888;height:6.5mm;}
.ln-alta{border-bottom:0.8pt solid #888;height:9mm;}
.fuente{font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;font-style:italic;}
.pauta{page-break-before:always;}
.pl{font-family:Arial,Helvetica,sans-serif;font-size:9pt;margin-bottom:1.6mm;text-align:justify;}
.pie{border-top:0.8pt solid #999;margin-top:5mm;padding-top:2mm;font-family:Arial,Helvetica,sans-serif;font-size:8.5pt;color:#555;display:flex;justify-content:space-between;gap:6mm;}
${FaroMarcador.cssImpresion()}
</style></head><body>${cuerpo}<div class="pie"><span>🏠 Proyecto Educativo F.A.R.O. · Estudio Mayor</span><span>🌡️ Las dos facturas${pieExtra||''}</span></div></body></html>`;
}
function _abreImpresion(doc){
  const win=window.open('','_blank','');
  if(!win){showToast('⚠️ Activa las ventanas emergentes para imprimir');return;}
  win.document.write(doc);win.document.close();setTimeout(()=>win.print(),400);
}
function imprimirLectura(clave){
  const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
  if(!meta||!card){showToast('⚠️ No se encontró la lectura');return;}
  sfx('click');
  const nota=card.querySelector('.lect-nota');
  const parrafos=[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  const cuerpo=`<div class="ruta"><span>🌡️ Ruta del Expediente Dorado · Etapa 4 de 7</span><span>Lecturas 📖</span></div>`
    +`<h1>${meta.titulo}</h1><div class="tipo">${meta.tipo}</div>`
    +`<div class="etiqueta"><strong>⚠️ Ejercicio de estilo de la casa, en homenaje.</strong> Este texto <strong>NO es obra de ese autor</strong>: lo escribió el Proyecto Educativo F.A.R.O. imitando su voz, y se declara como pastiche. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro del texto es real y comprobable</strong>; el único artificio permitido es la voz.${meta.ficcion?' '+meta.ficcion:''}</div>`
    +`<div class="idline"><span>Lee:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
    +parrafos;
  _abreImpresion(_hojaImpresa(meta.titulo,cuerpo+FaroMarcador.impresionExtra([clave]),' · '+meta.titulo));
}
function imprimirTodasLasLecturas(){
  sfx('click');
  let cuerpo=`<div class="ruta"><span>🌡️ Ruta del Expediente Dorado · Etapa 4 de 7</span><span>Las cinco lecturas 📖</span></div>`
    +`<h1>Las cinco lecturas de «Las dos facturas»</h1><div class="tipo">Un cuento, un capítulo de caballerías, un ensayo, una entrevista y una conversación, sobre las mismas cifras</div>`
    +`<div class="etiqueta"><strong>⚠️ Ejercicios de estilo de la casa, en homenaje.</strong> Los cinco textos <strong>NO son obra de Jorge Luis Borges, de Miguel de Cervantes Saavedra ni de Yuval Noah Harari</strong>, ni de Carmen Aristegui, Thomas Piketty, Jesús Quintero o Antonio Gala: los escribió el Proyecto Educativo F.A.R.O. imitando sus voces, y se declaran como pastiche. Las dos entrevistas son <strong>imaginadas: el encuentro nunca ocurrió</strong>; las personas son reales. Regla extra de la casa: <strong>toda obra, fecha y persona citada dentro de los textos es real y comprobable</strong>; el único artificio permitido es la voz.</div>`;
  ['borges','cervantes','harari','entrevista','gala'].forEach((clave,i)=>{
    const meta=LECTURAS_IMPR[clave];const card=document.getElementById('lect-'+clave);
    if(!card)return;
    const nota=card.querySelector('.lect-nota');
    cuerpo+=(i?'<div style="page-break-before:always;"></div>':'')
      +`<h2>${i+1}. ${meta.titulo}</h2><div class="tipo">${meta.tipo}</div>`
      +(nota?`<p class="fuente">${nota.textContent}</p>`:'')
      +[...card.querySelectorAll('.lect-p')].map(p=>'<p class="t">'+p.innerHTML+'</p>').join('');
  });
  _abreImpresion(_hojaImpresa('Las cinco lecturas',cuerpo+FaroMarcador.impresionExtra(null),' · Las cinco lecturas'));
}
function imprimirPreguntasLecturas(){
  sfx('click');
  const lineas=(n,alta)=>Array(n).fill('<div class="'+(alta?'ln-alta':'ln')+'"></div>').join('');
  let cuerpo=`<div class="ruta"><span>🌡️ Ruta del Expediente Dorado · Etapa 4 de 7</span><span>Preguntas de las lecturas 📖</span></div>`
    +`<h1>Preguntas de las cinco lecturas</h1><div class="tipo">Las dos facturas · 25 de comprensión lectora, 10 de completar y 10 de análisis complejo</div>`
    +`<div class="idline"><span>Nombre:</span><span class="r"></span><span>Fecha:</span><span class="r" style="max-width:35mm"></span></div>`
    +`<div class="etiqueta">Se responde <strong>con los cinco textos delante</strong>: no es un examen de memoria. Las respuestas de las tres secciones van en la <strong>pauta de la última hoja</strong>, así que se resuelve antes de darle la vuelta. Los cinco textos son <strong>ejercicios de estilo de la casa, no obra de Borges, Cervantes ni Harari</strong>, y las dos entrevistas (con Piketty a la manera de Aristegui, y la de Quintero con Gala) son <strong>imaginadas: el encuentro nunca ocurrió</strong>.</div>`;
  cuerpo+='<div class="sec">I. Comprensión lectora (25 preguntas)</div>';
  lectComprensionBank.forEach((q,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${q.q} <span class="fuente">(${q.t})</span></div>`;
    q.o.forEach(o=>{cuerpo+=`<div class="op">${o}</div>`;});
  });
  cuerpo+='<div class="sec">II. Completa la oración (10 preguntas)</div>';
  lectCompletarBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q.replace('___','_______________')} <span class="fuente">(${d.t})</span></div>`;
  });
  cuerpo+='<div class="sec">III. Análisis complejo (10 preguntas)</div>';
  lectAnalisisBank.forEach((d,i)=>{
    cuerpo+=`<div class="q"><span class="n">${i+1}.</span> ${d.q}</div>`+lineas(3,true);
  });
  cuerpo+='<div class="pauta"><div class="sec">✅ Pauta completa de respuestas</div>';
  cuerpo+='<div class="pl"><strong>I. Comprensión lectora:</strong> '+lectComprensionBank.map((q,i)=>(i+1)+') '+'abcd'[q.c]).join(' · ')+'</div>';
  cuerpo+='<div class="pl"><strong>II. Completar:</strong> '+lectCompletarBank.map((d,i)=>(i+1)+') '+d.a).join(' · ')+'</div>';
  cuerpo+='<div class="pl" style="margin-top:2mm;"><strong>III. Análisis complejo (guías de corrección):</strong></div>';
  lectAnalisisBank.forEach((d,i)=>{cuerpo+=`<div class="pl"><strong>${i+1}.</strong> ${d.guia}</div>`;});
  cuerpo+='</div>';
  _abreImpresion(_hojaImpresa('Preguntas de las lecturas',cuerpo,' · Preguntas de las lecturas'));
}

// ===================== DIPLOMA =====================
function _diplPct(){return xp>=MXP?100:Math.round((xp/MXP)*100);}
function openDiploma(){sfx('fan');const pct=_diplPct();document.getElementById('diplPct').textContent=pct+'%';document.getElementById('diplBar').style.width=pct+'%';document.getElementById('diplDate').textContent='Fecha: '+new Date().toLocaleDateString('es-HN',{year:'numeric',month:'long',day:'numeric'});const msgs=['¡Sigue llenando la hoja de la factura!','¡Muy buen trabajo!','¡Aprendiz de lectura de cifras!','¡Ya no escoges la punta del rango!','¡Pones la cifra de pie y dices quién paga!'];document.getElementById('diplMsg').textContent=msgs[Math.min(Math.floor(pct/25),4)];const stars=['⭐','⭐⭐','⭐⭐⭐'];document.getElementById('diplStars').textContent=stars[Math.min(Math.floor(pct/40),2)];const achTxt=unlockedAch.map(id=>ACHIEVEMENTS[id].icon+' '+ACHIEVEMENTS[id].label).join(' · ');document.getElementById('diplAch').textContent=achTxt||'Sigue completando secciones para desbloquear logros';document.getElementById('diplomaOverlay').classList.add('open');launchConfetti();}
function closeDiploma(){document.getElementById('diplomaOverlay').classList.remove('open');}
function updateDiplomaName(v){document.getElementById('diplName').textContent=v||'Estudiante';}
function shareWA(){const name=document.getElementById('diplName').textContent||'Estudiante';const pct=_diplPct();const msg='🌡️ ¡'+name+' completó la Etapa 4 de la Ruta del Expediente Dorado (Las dos facturas)! 🏅 Progreso: '+pct+'% · 🌡️ policastsapien.com';window.open('https://wa.me/?text='+encodeURIComponent(msg),'_blank');}
async function captureDiploma(){if(typeof html2canvas==='undefined'){showToast('⚠️ Cargando... intenta de nuevo');return;}sfx('click');const card=document.querySelector('.diploma-card');const btn=document.querySelector('.diploma-actions .btn-pri');const toHide=[card.querySelector('.diploma-input'),card.querySelector('.diploma-actions'),card.querySelector('hr')];if(btn){btn.disabled=true;btn.textContent='⏳ Capturando...';}toHide.forEach(el=>{if(el)el.style.display='none';});let dataUrl='';try{const canvas=await html2canvas(card,{scale:2,useCORS:true,backgroundColor:'#ffffff'});toHide.forEach(el=>{if(el)el.style.display='';});dataUrl=canvas.toDataURL('image/png');const name=(document.getElementById('diplName').textContent||'Estudiante').replace(/\s+/g,'-');const fileName='constancia-'+name+'.png';const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins?.Filesystem&&cap.Plugins?.Share){const base64Data=dataUrl.split(',')[1];const result=await cap.Plugins.Filesystem.writeFile({path:fileName,data:base64Data,directory:'CACHE'});await cap.Plugins.Share.share({url:result.uri,dialogTitle:'Guardar / Compartir Constancia'});}else{const a=document.createElement('a');a.href=dataUrl;a.download=fileName;a.click();}}catch(e){toHide.forEach(el=>{if(el)el.style.display='';});if(e.name!=='AbortError')showToast('⚠️ No se pudo guardar la constancia');}finally{if(btn){btn.disabled=false;btn.textContent='📷 Guardar foto';}}}

